def inr_format(n):
    s = str(n)
    if len(s) <= 3:
        return s
    result = []
    i = len(s) - 1
    while i >= 0:
        if i % 2 == 0 and i != len(s) - 1:
            result.append(',')
        result.append(s[i])
        i -= 1
    return ''.join(reversed(result))

def inr_format(n):
    s = str(n)[::-1]
    grouped = []
    i = 0
    while i < len(s):
        grouped.append(s[i:i+2][::-1])
        i += 2
    return ','.join(grouped[::-1])

