def emi(P, rate, n):
    if rate == 0:
        return round(P / n, 2)
    i = rate / 100 / 12
    numerator = P * i * (1 + i) ** n
    denominator = (1 + i) ** n - 1
    emi = numerator / denominator
    return round(emi, 2)

